"""Локальная база данных хэшей и последовательностей белков для SIGMA v1.2"""
import hashlib


def _generate_hash(sequence: str) -> str:
    """Генерирует MD5-хэш последовательности"""
    return hashlib.md5(sequence.encode()).hexdigest()


